<template>
    <h1>CRUD Productos</h1>
    {{ producto }}


    <form @submit.prevent="funGuardarProducto()">

        <label for="">Ingrese nombre:</label>
        <input type="text" v-model="producto.nombre">
        <br>
        <label for="">Ingrese precio:</label>
        <input type="text" v-model="producto.precio">
        <br>
        <label for="">Ingrese descripcion:</label>
        <textarea v-model="producto.descripcion"></textarea>
        <br>
        <label for="">Ingrese imagen:</label>
        <input type="text" v-model="producto.imagen">
        <br>
        <button type="submit">Guardar</button>




    </form>

    <table border="1">
        <thead>
            <tr>
                <th>ID</th>
                <th>NOMBRE</th>
                <th>PRECIO</th>
                <th>DESCRIPCION</th>
                <th>IMAGEN</th>
                <th>ACCION</th>
           </tr>
        </thead>

        <tbody>
            <tr v-for="(prod,posicion) in productos" :key="prod.id">
                <td>{{ posicion+1 }}</td>
                <td>{{ prod.nombre}}</td>
                <td>{{ prod.precio}}</td>
                <td>{{ prod.descripcion}}</td>
                <td>
                    <img :src="prod.imagen" alt="" width="50px">
                </td>
                <td>
                    <button @click="funEditar(prod)">editar</button>
                    <button>eliminar</button>
                </td>
            </tr>

        </tbody>
        
       
    </table>



    <pre>{{ productos }}</pre>


</template>


<script setup>

    import { ref } from 'vue';

    //declaramos variables
    const productos=ref([
        {id:1, nombre:"Laptop",precio:2590.00,descripcion:"",imagen:"data:image/jpeg;base64,"},
        {id:2,nombre:"Teclado",precio:259.00,descripcion:"", imagen:"data:image/jpeg;base64,"}


    ]);

    const producto=ref({"nombre":"","precio":0,"descripcion":"","imagen":""})

    function funGuardarProducto(){
        productos.value.push(producto.value);
    }

    function funEditar(prod){
        producto.value=prod;

    }
</script>